WITH params AS (SELECT coalesce(%s::text, '') AS line_code, coalesce(%s::text, '') AS branch_code, coalesce(%s::text, '') AS status, %s::integer AS authenticated_user_id, %s::integer AS row_limit), scope AS (SELECT p.*, u.user_id AS authorized_user_id, coalesce(u.ds_branchs, '') AS ds_branchs, coalesce(u.is_super, 0) = 1 OR coalesce(u.ds_branchs, '') = '' AS unrestricted FROM params p LEFT JOIN public.userinfo u ON u.user_id = p.authenticated_user_id)
SELECT l.line_code, l.line_name, l.line_name2, l.branch_code, l.line_group_code, l.resource_code, l.factory_code, l.line_group_code1, l.line_group_code2, l.line_group_code3, l.allow_retrieve_yn, l.status, l.date0, l.time0, l.user_id0, l.date2, l.time2, l.user_id2, l.user_appr, l.date_appr, l.time_appr, count(*) OVER () AS total
FROM public.mflist_line l CROSS JOIN scope s
WHERE s.authorized_user_id IS NOT NULL AND (s.line_code = '' OR l.line_code = ANY(string_to_array(s.line_code, ','))) AND (s.branch_code = '' OR l.branch_code = ANY(string_to_array(s.branch_code, ','))) AND (s.status = '' OR l.status::text = ANY(string_to_array(s.status, ','))) AND (s.unrestricted OR l.branch_code = ANY(string_to_array(s.ds_branchs, ',')))
ORDER BY l.line_code LIMIT (SELECT row_limit FROM params);
